use xiom.io;

use xiom.string;
use xiom.convert.tostring;
module my_math {
  pub fn is_prime(n: Int) -> Bool {
    if n < 2 { return false; };
    var i = 2;
    while i * i <= n {
      if n % i == 0 { return false; };
      i += 1;
    };
    true
  }

  pub fn gcd(a: Int, b: Int) -> Int {
    var x = a;
    var y = b;
    while y != 0 {
      let temp = y;
      y = x % y;
      x = temp;
    };
    x
  }
}

module my_string {
  pub fn reverse(s: Str) -> Str {
    var result = "";
    var i = s.len();
    while i > 0 {
      i -= 1;
      result = string.str_concat(result, to_string_char(s.char_at(i)));
    };
    result
  }

  pub fn count_words(s: Str) -> Int {
    if s.len() == 0 { return 0; };
    var count = 0;
    var in_word = false;
    var i = 0;
    while i < s.len() {
      let ch = s.char_at(i);
      if ch == ' ' { in_word = false; }
      else if !in_word { count += 1; in_word = true; };
      i += 1;
    };
    count
  }
}

module my_collections {
  pub type VecStack[T] = {
    items: Vec[T];
  }

  pub fn VecStack.push[T](&mut self, item: T) {
    self.items.push(item);
  }
}

fn main() -> Int {

  let prime = my_math.is_prime(17);
  io.println(prime.to_str());

  let rev = my_string.reverse("XIOM");
  io.println(rev.to_str());

  let words = my_string.count_words("hello world");
  io.println(words.to_str());

  var stack: my_collections.VecStack[Int] = my_collections.VecStack{ items: Vec[Int].new() };
  stack.push(42);
  io.println(stack.items.get(0).unwrap().to_str());

  return 0;
}
